{
  "hechos": [
    {"id": "H1", "texto": "El puente La Concordia fue cerrado al tránsito de vehículos y peatones.", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P5", "P6", "P7"]},
    {"id": "H2", "texto": "Por el puente pasan a diario unos 9.000 vehículos.", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P5", "P6", "P7"]},
    {"id": "H3", "texto": "La ruta alterna por El Cedral alarga el trayecto en aproximadamente 40 minutos.", "tipo": "dato", "paginas": ["P1", "P2", "P5", "P6", "P7"]},
    {"id": "H4", "texto": "La situación sigue en desarrollo.", "tipo": "atribucion", "paginas": ["P2", "P3", "P4", "P7"]},
    {"id": "H5", "texto": "Un contratista que pidió reserva de su nombre dijo que las grietas se habían reportado hace un año.", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P6"]},
    {"id": "H6", "texto": "La revisión técnica halló que dos vigas de soporte presentan grietas.", "tipo": "dato", "paginas": ["P5", "P7"]},
    {"id": "H7", "texto": "Las autoridades de Villa Miranda prohibieron el paso de carros y peatones por el puente La Concordia.", "tipo": "dato", "paginas": ["P1", "P3"]}
